// Localization access, as an extension so call sites read `context.l10n.editName`.
//
// `AppLocalizations` is generated by `flutter gen-l10n` from lib/l10n/*.arb.
// Its getters are non-nullable (`nullable-getter: false` in l10n.yaml).

import 'package:flutter/widgets.dart';

import '../l10n/app_localizations.dart';

export '../l10n/app_localizations.dart' show AppLocalizations;

/// `context.l10n.<key>`.
extension AppLocalizationsX on BuildContext {
  /// The strings for the current locale.
  AppLocalizations get l10n => AppLocalizations.of(this);
}
